#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int main(){ int n, limit; if(!(cin>>n>>limit)) return 0; vector<int> w(n); for(int i=0;i<n;i++) cin>>w[i]; sort(w.begin(), w.end()); int l=0,r=n-1,ans=0; while(l<=r){ if(l<r && w[l]+w[r]<=limit) l++; r--; ans++; } cout<<ans<<'\n'; return 0; }
